def nCr_mod_p(n, r, p):
    if r > n:
        return 0
    if r == 0 or r == n:
        return 1
    # Lucas 定理分解
    res = 1
    while n > 0 or r > 0:
        ni = n % p
        ri = r % p
        if ri > ni:
            return 0
        # 计算 C(ni, ri) mod p
        num = 1
        den = 1
        for i in range(ri):
            num = (num * (ni - i)) % p
            den = (den * (i + 1)) % p
        res = (res * num * modinv(den, p)) % p
        n //= p
        r //= p
    return res

