def solve():
    n, k, p = map(int, input().split())
    # 利用周期性
    if n >= p:
        # 计算全周期和
        sum_full = 0
        for i in range(1, p):
            sum_full = (sum_full + pow(i, k, p)) % p
        # 注意 i=p 时 pow(p,k,p)=0
        cycles = n // p
        rem = n % p
        sum_rem = 0
        for i in range(1, rem+1):
            sum_rem = (sum_rem + pow(i, k, p)) % p
        ans = (cycles * sum_full + sum_rem) % p
    else:
        ans = 0
        for i in range(1, n+1):
            ans = (ans + pow(i, k, p)) % p
    print(ans)

