import math

def bsgs(a, b, p):
    a %= p
    b %= p
    if b == 1:
        return 0
    m = int(math.isqrt(p)) + 1
    # baby steps: store a^j * b mod p
    table = {}
    e = 1
    for j in range(m):
        if e not in table:
            table[e] = j
        e = (e * a) % p
    # giant step: factor = a^(-m)
    factor = pow(a, p-1-m, p)  # 因为 a^(p-1)=1，所以 a^(-m)=a^(p-1-m)
    gamma = 1
    for i in range(m):
        if gamma in table:
            x = i * m + table[gamma]
            if pow(a, x, p) == b:
                return x
        gamma = (gamma * factor) % p
    return -1

def solve():
    a, b, p = map(int, input().split())
    print(bsgs(a, b, p))

