import sys

MOD = 10**9 + 7

def build_tree(arr, node, start, end):
    if start == end:
        tree[node] = arr[start] % MOD
    else:
        mid = (start + end) // 2
        build_tree(arr, node*2, start, mid)
        build_tree(arr, node*2+1, mid+1, end)
        tree[node] = (tree[node*2] * tree[node*2+1]) % MOD

def update(node, start, end, l, r, x):
    if lazy[node] != 1:
        tree[node] = (tree[node] * pow(lazy[node], end-start+1, MOD)) % MOD
        if start != end:
            lazy[node*2] = (lazy[node*2] * lazy[node]) % MOD
            lazy[node*2+1] = (lazy[node*2+1] * lazy[node]) % MOD
        lazy[node] = 1
    if r < start or end < l:
        return
    if l <= start and end <= r:
        tree[node] = (tree[node] * pow(x, end-start+1, MOD)) % MOD
        if start != end:
            lazy[node*2] = (lazy[node*2] * x) % MOD
            lazy[node*2+1] = (lazy[node*2+1] * x) % MOD
        return
    mid = (start + end) // 2
    update(node*2, start, mid, l, r, x)
    update(node*2+1, mid+1, end, l, r, x)
    tree[node] = (tree[node*2] * tree[node*2+1]) % MOD

def query(node, start, end, l, r):
    if lazy[node] != 1:
        tree[node] = (tree[node] * pow(lazy[node], end-start+1, MOD)) % MOD
        if start != end:
            lazy[node*2] = (lazy[node*2] * lazy[node]) % MOD
            lazy[node*2+1] = (lazy[node*2+1] * lazy[node]) % MOD
        lazy[node] = 1
    if r < start or end < l:
        return 1
    if l <= start and end <= r:
        return tree[node]
    mid = (start + end) // 2
    return (query(node*2, start, mid, l, r) * query(node*2+1, mid+1, end, l, r)) % MOD

def main():
    global tree, lazy
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    idx = 0
    n = int(data[idx]); q = int(data[idx+1]); idx += 2
    arr = [0] + [int(data[idx+i]) for i in range(n)]; idx += n
    tree = [1] * (4*n)
    lazy = [1] * (4*n)
    build_tree(arr, 1, 1, n)
    out = []
    for _ in range(q):
        typ = int(data[idx]); idx += 1
        if typ == 1:
            l = int(data[idx]); r = int(data[idx+1]); x = int(data[idx+2]); idx += 3
            update(1, 1, n, l, r, x % MOD)
        else:
            l = int(data[idx]); r = int(data[idx+1]); idx += 2
            out.append(str(query(1, 1, n, l, r)))
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

