def mod_pow(a, b, m):
    res = 1
    a %= m
    while b:
        if b & 1:
            res = (res * a) % m
        a = (a * a) % m
        b >>= 1
    return res

def precompute():
    for i in range(1, MAXN + 1):
        fact[i] = fact[i-1] * i % MOD
    inv_fact[MAXN] = mod_pow(fact[MAXN], MOD-2, MOD)
