def geom_sum(a, n, p):
    # 求 1 + a + a^2 + ... + a^(n-1) mod p, n 可能很大
    if n == 0:
        return 0
    if n == 1:
        return 1 % p
    if n % 2 == 0:
        half = geom_sum(a, n//2, p)
        return half * (1 + mod_pow(a, n//2, p)) % p
    else:
        return (geom_sum(a, n-1, p) + mod_pow(a, n-1, p)) % p

def main():
