import sys

class SegmentTree:
    def __init__(self, data, p):
        self.n = len(data)
        self.p = p
        self.size = 1
        while self.size < self.n:
            self.size <<= 1
        self.tree = [1] * (2*self.size)
        for i in range(self.n):
            self.tree[self.size+i] = data[i] % p
        for i in range(self.size-1, 0, -1):
            self.tree[i] = self.tree[2*i] * self.tree[2*i+1] % p
    def update(self, pos, val):
        i = self.size + pos
        self.tree[i] = val % self.p
        i //= 2
        while i:
            self.tree[i] = self.tree[2*i] * self.tree[2*i+1] % self.p
            i //= 2
    def query(self, l, r):
        res = 1
        l += self.size
        r += self.size
        while l <= r:
            if l & 1:
                res = res * self.tree[l] % self.p
                l += 1
            if not (r & 1):
                res = res * self.tree[r] % self.p
                r -= 1
            l //= 2
            r //= 2
        return res

def mod_pow(a, b, p):
    a %= p
    res = 1
    while b > 0:
        if b & 1:
            res = res * a % p
        a = a * a % p
        b >>= 1
    return res

