def tonelli_shanks(a, p):
    if a == 0:
        return 0
    if legendre(a, p) != 1:
        return None
    if p % 4 == 3:
        return pow_mod(a, (p+1)//4, p)
    # 分解 p-1 = q * 2^s
    q = p-1
    s = 0
    while q % 2 == 0:
        q //= 2
        s += 1
    # 寻找非二次剩余
