        i = 1
        temp = t * t % p
        while temp != 1:
            temp = temp * temp % p
            i += 1
        b = pow_mod(c, 1 << (m-i-1), p)
        r = r * b % p
        t = t * b * b % p
        c = b * b % p
        m = i
    return r

