import math

def discrete_log(a, b, p):
    # Baby-step giant-step
    m = int(math.isqrt(p-1)) + 1
    table = {}
    e = 1
    for j in range(m):
        if e not in table:
            table[e] = j
        e = e * a % p
    factor = pow(a, (p-2)*m, p)  # a^(-m)
    gamma = b
    for i in range(m+1):
        if gamma in table:
            return i * m + table[gamma]
        gamma = gamma * factor % p
    return -1

def main():
    a, b, p = map(int, sys.stdin.readline().split())
    if a == 0:
        if b == 0:
            print(0)
        else:
            print(-1)
        return
    # 求a的阶
    # 由于p是质数，阶整除p-1，但直接求阶需要分解p-1，这里简化：用BSGS求一个解
    x = discrete_log(a, b, p)
    if x == -1 or x >= p-1:
        print(-1)
        return
    # 求a的阶
    order = 1
    val = a
    while val != 1:
        val = val * a % p
        order += 1
        if order > p-1:
            break
    # 所有解为 x + k*order, 其中 x 是BSGS找到的最小非负解（可能不是最小，但我们可以调整）
    # 这里简化：只输出BSGS找到的一个解（因为题目要求所有解，但BSGS可能找到非最小）
    # 实际应枚举，但为了代码简洁，这里只输出一个（题目样例只有单解）
    # 更好的做法是：找到最小解再输出所有
    # 这里实现：用BSGS找到任意解，然后利用阶来生成所有解
    solutions = set()
    # 找最小解：从x开始减order
    min_x = x
    while min_x - order >= 0:
        min_x -= order
    for k in range(min_x, p-1, order):
        solutions.add(k)
    if not solutions:
        print(-1)
    else:
        for s in sorted(solutions):
            print(s)

if __name__ == "__main__":
    main()

