import math

def bsgs(a, b, p):
    # 求 a^x ≡ b (mod p) 的最小非负整数 x，p 为素数
    a %= p
    if b == 1:
        return 0
    if a == 0:
        return -1 if b != 0 else 1
    m = int(math.isqrt(p)) + 1
    table = {}
    cur = 1
    for j in range(m):
        if cur not in table:
            table[cur] = j
        cur = (cur * a) % p
    # 计算 a^{-m} mod p
    inv = pow(pow(a, m, p), p-2, p)
    cur = b
    for i in range(m):
        if cur in table:
            ans = i * m + table[cur]
            if ans < p:  # 因为周期最多 p-1
                return ans
        cur = (cur * inv) % p
    return -1

