        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    return lower[:-1] + upper[:-1]

def circumcircle(p1, p2, p3):
    ax, ay = p1; bx, by = p2; cx, cy = p3
    d = 2*(ax*(by-cy) + bx*(cy-ay) + cx*(ay-by))
    if abs(d) < 1e-12:
        return None
    ux = ((ax*ax+ay*ay)*(by-cy) + (bx*bx+by*by)*(cy-ay) + (cx*cx+cy*cy)*(ay-by)) / d
    uy = ((ax*ax+ay*ay)*(cx-bx) + (bx*bx+by*by)*(ax-cx) + (cx*cx+cy*cy)*(bx-ax)) / d
    r = math.hypot(ux-ax, uy-ay)
    return (ux, uy, r)

def min_enclosing_circle(points):
    random.shuffle(points)
    c = (points[0][0], points[0][1], 0.0)
    for i in range(1, len(points)):
        if math.hypot(points[i][0]-c[0], points[i][1]-c[1]) > c[2] + 1e-9:
            c = (points[i][0], points[i][1], 0.0)
            for j in range(i):
                if math.hypot(points[j][0]-c[0], points[j][1]-c[1]) > c[2] + 1e-9:
                    c = ((points[i][0]+points[j][0])/2, (points[i][1]+points[j][1])/2, math.hypot(points[i][0]-points[j][0], points[i][1]-points[j][1])/2)
                    for k in range(j):
                        if math.hypot(points[k][0]-c[0], points[k][1]-c[1]) > c[2] + 1e-9:
                            circ = circumcircle(points[i], points[j], points[k])
                            if circ:
                                c = circ
    return c

