def point_in_convex_polygon(poly, p):
    m = len(poly)
    if m == 0:
        return False
    if m == 1:
        return poly[0] == p
    if m == 2:
        # 检查是否在线段上
        a,b = poly
        return cross(a,b,p) == 0 and min(a[0],b[0]) <= p[0] <= max(a[0],b[0]) and min(a[1],b[1]) <= p[1] <= max(a[1],b[1])
