def point_in_convex_polygon(poly, p):
    m = len(poly)
    if m == 1:
        return p == poly[0]
    if m == 2:
        return cross(poly[0], poly[1], p) == 0 and min(poly[0][0], poly[1][0]) <= p[0] <= max(poly[0][0], poly[1][0]) and min(poly[0][1], poly[1][1]) <= p[1] <= max(poly[0][1], poly[1][1])
    if cross(poly[0], poly[1], p) < 0 or cross(poly[0], poly[-1], p) > 0:
