    l = 1; r = m-1
    while r - l > 1:
        mid = (l+r)//2
        if cross(poly[0], poly[mid], p) >= 0:
            l = mid
        else:
            r = mid
    return cross(poly[l], poly[(l+1)%m], p) >= 0

