def dist(a,b):
    return math.hypot(a[0]-b[0], a[1]-b[1])

def circle_from2(a,b):
    cx = (a[0]+b[0])/2.0
    cy = (a[1]+b[1])/2.0
    r = dist(a,b)/2.0
    return (cx,cy,r)

def circle_from3(a,b,c):
    ax,ay = a; bx,by = b; cx,cy = c
    d = 2*(ax*(by-cy) + bx*(cy-ay) + cx*(ay-by))
    if abs(d) < 1e-12:
        return None
    ux = ((ax*ax+ay*ay)*(by-cy) + (bx*bx+by*by)*(cy-ay) + (cx*cx+cy*cy)*(ay-by))/d
    uy = ((ax*ax+ay*ay)*(cx-bx) + (bx*bx+by*by)*(ax-cx) + (cx*cx+cy*cy)*(bx-ax))/d
    r = dist((ax,ay),(ux,uy))
    return (ux,uy,r)

def min_circle(points):
    # 随机增量法
    random.shuffle(points)
    c = (points[0][0], points[0][1], 0.0)
    for i in range(1, len(points)):
        if dist(points[i], (c[0],c[1])) > c[2] + 1e-9:
            c = (points[i][0], points[i][1], 0.0)
            for j in range(i):
                if dist(points[j], (c[0],c[1])) > c[2] + 1e-9:
                    c = circle_from2(points[i], points[j])
                    for k in range(j):
                        if dist(points[k], (c[0],c[1])) > c[2] + 1e-9:
                            c = circle_from3(points[i], points[j], points[k])
    return c

