def point_in_convex_polygon(pt, hull):
    m = len(hull)
    if m == 1:
        return pt == hull[0]
    if m == 2:
        return cross(hull[0], hull[1], pt) == 0 and min(hull[0][0], hull[1][0]) <= pt[0] <= max(hull[0][0], hull[1][0]) and min(hull[0][1], hull[1][1]) <= pt[1] <= max(hull[0][1], hull[1][1])
    # 检查是否在三角形(hull[0], hull[1], hull[2])内，用角度法或二分
    if cross(hull[0], hull[1], pt) < 0 or cross(hull[0], hull[-1], pt) > 0:
        return False
    lo, hi = 1, m-1
    while hi - lo > 1:
        mid = (lo+hi)//2
        if cross(hull[0], hull[mid], pt) >= 0:
            lo = mid
        else:
            hi = mid
    return cross(hull[lo], hull[hi], pt) >= 0

