    cx = (p1.x + p2.x) / 2
    cy = (p1.y + p2.y) / 2
    r2 = dist2(p1, p2) / 4
    return (cx, cy, r2)

def circle_from_three(p1, p2, p3):
    ax, ay = p1.x, p1.y
    bx, by = p2.x, p2.y
    cx, cy = p3.x, p3.y
    d = 2 * (ax*(by - cy) + bx*(cy - ay) + cx*(ay - by))
