def point_in_convex_polygon(hull, p):
    m = len(hull)
    if m == 0:
        return False
    if m == 1:
        return p == hull[0]
    if m == 2:
        return cross(hull[0], hull[1], p) == 0 and min(hull[0][0], hull[1][0]) <= p[0] <= max(hull[0][0], hull[1][0]) and min(hull[0][1], hull[1][1]) <= p[1] <= max(hull[0][1], hull[1][1])
    # 检查是否在三角形0-1-2内
    if cross(hull[0], hull[1], p) < 0:
        return False
    if cross(hull[0], hull[-1], p) > 0:
        return False
    # 二分找到夹住p的边
    l, r = 1, m-1
    while l < r:
        mid = (l+r)//2
        if cross(hull[0], hull[mid], p) >= 0:
            l = mid+1
        else:
            r = mid
    if l == m:
        l = m-1
    # 检查在三角形0-l-1内
    if cross(hull[0], hull[l], p) < 0:
        return False
    if cross(hull[l], hull[(l+1)%m], p) < 0:
        return False
    if cross(hull[(l+1)%m], hull[0], p) < 0:
        return False
    return True

