import sys
import math

def cross(o, a, b):
    return (a[0]-o[0])*(b[1]-o[1]) - (a[1]-o[1])*(b[0]-o[0])

def dot(a, b):
    return a[0]*b[0] + a[1]*b[1]

def dist_point_segment(p, a, b):
    # 点到线段的最短距离
    ab = (b[0]-a[0], b[1]-a[1])
    ap = (p[0]-a[0], p[1]-a[1])
    if dot(ab, ab) == 0:
        return math.hypot(ap[0], ap[1])
    t = dot(ap, ab) / dot(ab, ab)
    if t < 0:
        t = 0
    elif t > 1:
        t = 1
    proj = (a[0] + t*ab[0], a[1] + t*ab[1])
    return math.hypot(p[0]-proj[0], p[1]-proj[1])

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    idx = 0
    n = int(data[idx]); idx += 1
    poly = []
    for i in range(n):
        x = int(data[idx]); y = int(data[idx+1]); idx += 2
        poly.append((x,y))
    q = int(data[idx]); idx += 1
    out = []
    for i in range(q):
        x = int(data[idx]); y = int(data[idx+1]); idx += 2
        p = (x,y)
        # 判断是否在多边形内部（含边界）
        # 简单方法：检查所有边的叉积方向
        inside = True
        for j in range(n):
            a = poly[j]
            b = poly[(j+1)%n]
            if cross(a, b, p) < 0:  # 由于逆时针，内部点应该使叉积>=0
                inside = False
                break
        if inside:
            # 内部：到所有边的最小距离
            min_dist = float('inf')
            for j in range(n):
                d = dist_point_segment(p, poly[j], poly[(j+1)%n])
                if d < min_dist:
                    min_dist = d
            out.append(f"{min_dist:.2f}")
        else:
            # 外部：到所有顶点和线段的最小距离
            min_dist = float('inf')
            for j in range(n):
                d = dist_point_segment(p, poly[j], poly[(j+1)%n])
                if d < min_dist:
                    min_dist = d
            # 到顶点距离已包含在线段中，但为了保险再检查顶点
            for v in poly:
                d = math.hypot(p[0]-v[0], p[1]-v[1])
                if d < min_dist:
                    min_dist = d
            out.append(f"{min_dist:.2f}")
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()

