def point_in_convex_polygon(poly, p):
    if len(poly) == 1:
        return poly[0] == p
    if len(poly) == 2:
        # 判断是否在线段上
        (x1,y1),(x2,y2) = poly[0], poly[1]
        (px,py) = p
        if cross(poly[0], poly[1], p) != 0:
            return False
        return min(x1,x2) <= px <= max(x1,x2) and min(y1,y2) <= py <= max(y1,y2)
    # 以 poly[0] 为基准，按极角二分
    n = len(poly)
    base = poly[0]
    # 检查是否在扇形内
    if cross(base, poly[1], p) < 0:
        return False
    if cross(base, poly[-1], p) > 0:
        return False
    # 二分找所在三角形
    l, r = 1, n-1
    while l < r:
        mid = (l+r)//2
        if cross(base, poly[mid], p) >= 0:
            r = mid
        else:
            l = mid+1
    idx = l
    if idx == n-1:
        # 检查最后一条边
        return cross(poly[-1], poly[0], p) >= 0
    else:
        return cross(poly[idx], poly[idx+1], p) >= 0

