import math

def dist2(a, b):
    return (a[0]-b[0])**2 + (a[1]-b[1])**2

def circumcircle(p1, p2, p3):
    # 返回圆心和半径平方
    ax, ay = p1; bx, by = p2; cx, cy = p3
    d = 2*(ax*(by-cy) + bx*(cy-ay) + cx*(ay-by))
    if abs(d) < 1e-12:
        return None
    ux = ((ax**2+ay**2)*(by-cy) + (bx**2+by**2)*(cy-ay) + (cx**2+cy**2)*(ay-by)) / d
    uy = ((ax**2+ay**2)*(cx-bx) + (bx**2+by**2)*(ax-cx) + (cx**2+cy**2)*(bx-ax)) / d
    r2 = dist2((ax,ay), (ux,uy))
    return (ux, uy, r2)

def min_enclosing_circle(points):
    random.shuffle(points)
    c = (points[0][0], points[0][1], 0.0)
    for i in range(1, len(points)):
        if dist2(points[i], (c[0], c[1])) > c[2] + 1e-12:
            c = (points[i][0], points[i][1], 0.0)
            for j in range(i):
                if dist2(points[j], (c[0], c[1])) > c[2] + 1e-12:
                    c = ((points[i][0]+points[j][0])/2.0, (points[i][1]+points[j][1])/2.0, dist2(points[i], points[j])/4.0)
                    for k in range(j):
                        if dist2(points[k], (c[0], c[1])) > c[2] + 1e-12:
                            res = circumcircle(points[i], points[j], points[k])
                            if res:
                                c = res
    return c

