            return
        self.push_down(node, l, r)
        mid = (l + r) // 2
        if ql <= mid:
            self.update(node*2, l, mid, ql, qr)
        if qr > mid:
            self.update(node*2+1, mid+1, r, ql, qr)
        self.cnt[node] = self.cnt[node*2] + self.cnt[node*2+1]

    def query(self, node, l, r, ql, qr):
        if ql <= l and r <= qr:
            return self.cnt[node]
        self.push_down(node, l, r)
        mid = (l + r) // 2
        res = 0
