class SegTree:
    def __init__(self, n):
        self.n = n
        self.tree = [Node() for _ in range(4 * n)]
        self.lazy = [0] * (4 * n)

    def merge(self, left, right):
        res = Node()
        res.sum = left.sum + right.sum
        res.pre = max(left.pre, left.sum + right.pre)
        res.suf = max(right.suf, right.sum + left.suf)
        res.best = max(left.best, right.best, left.suf + right.pre)
        return res

    def apply(self, idx, l, r, val):
        length = r - l + 1
        self.tree[idx].sum += val * length
        self.tree[idx].pre += val * length
        self.tree[idx].suf += val * length
        self.tree[idx].best += val * length  # 注意：如果全是负数，best可能为负，但题目允许空子段，所以best至少为0，但这里直接加可能出错，需处理
        self.lazy[idx] += val

    def push_down(self, idx, l, r):
        if self.lazy[idx] != 0 and l != r:
            mid = (l + r) // 2
            self.apply(idx*2, l, mid, self.lazy[idx])
            self.apply(idx*2+1, mid+1, r, self.lazy[idx])
            self.lazy[idx] = 0

    def update(self, idx, l, r, ql, qr, val):
        if ql <= l and r <= qr:
            self.apply(idx, l, r, val)
            return
        self.push_down(idx, l, r)
        mid = (l + r) // 2
        if ql <= mid:
            self.update(idx*2, l, mid, ql, qr, val)
        if qr > mid:
            self.update(idx*2+1, mid+1, r, ql, qr, val)
        self.tree[idx] = self.merge(self.tree[idx*2], self.tree[idx*2+1])

    def query(self, idx, l, r, ql, qr):
        if ql <= l and r <= qr:
            return self.tree[idx]
        self.push_down(idx, l, r)
        mid = (l + r) // 2
        if qr <= mid:
            return self.query(idx*2, l, mid, ql, qr)
        elif ql > mid:
            return self.query(idx*2+1, mid+1, r, ql, qr)
        else:
            left = self.query(idx*2, l, mid, ql, qr)
            right = self.query(idx*2+1, mid+1, r, ql, qr)
            return self.merge(left, right)

