def kmp_search(s, p):
    n, m = len(s), len(p)
    # 计算next数组
    next_arr = [0] * m
    j = 0
    for i in range(1, m):
        while j > 0 and p[i] != p[j]:
            j = next_arr[j-1]
        if p[i] == p[j]:
            j += 1
            next_arr[i] = j
    # 匹配
    res = []
    j = 0
    for i in range(n):
        while j > 0 and s[i] != p[j]:
            j = next_arr[j-1]
        if s[i] == p[j]:
            j += 1
        if j == m:
            res.append(i - m + 2)  # 转为1-based
            j = next_arr[j-1]
    return res

