def min_cycle(s):
    n = len(s)
    # 计算next数组
    next_arr = [0] * n
    j = 0
    for i in range(1, n):
        while j > 0 and s[i] != s[j]:
            j = next_arr[j-1]
        if s[i] == s[j]:
            j += 1
            next_arr[i] = j
    # 最小循环节长度 = n - next[n-1]，但需要验证能否整除
    len_cycle = n - next_arr[-1]
    if n % len_cycle == 0:
        return len_cycle
    else:
        return n

