    for i in range(1, m):
        while j > 0 and P[i] != P[j]:
            j = lps[j-1]
        if P[i] == P[j]:
            j += 1
        lps[i] = j
    # 对每个位置计算最长匹配长度
    match_len = [0] * n
    j = 0
    for i in range(n):
        while j > 0 and S[i] != P[j]:
            j = lps[j-1]
        if S[i] == P[j]:
            j += 1
        match_len[i] = j
        if j == m:
            j = lps[j-1]
    max_len = max(match_len)
    positions = [i for i, val in enumerate(match_len) if val == max_len]
    print(max_len)
    print(len(positions))
