def min_rotation(s):
    n = len(s)
    ss = s + s
    i, j, k = 0, 1, 0
    while i < n and j < n and k < n:
        a = ss[i+k]
        b = ss[j+k]
        if a == b:
            k += 1
        elif a > b:
            i = i + k + 1
            if i == j:
                i += 1
            k = 0
        else:
            j = j + k + 1
            if i == j:
                j += 1
            k = 0
    return min(i, j)

