from collections import deque

class Dinic:
    def __init__(self, n):
        self.n = n
        self.adj = [[] for _ in range(n)]
        self.cap = {}

    def add_edge(self, u, v, c):
        if (u, v) in self.cap:
            self.cap[(u, v)] += c
        else:
            self.adj[u].append(v)
            self.adj[v].append(u)
            self.cap[(u, v)] = c
            self.cap[(v, u)] = 0

    def bfs(self, s, t):
        self.level = [-1]*self.n
        q = deque([s])
        self.level[s] = 0
        while q:
            u = q.popleft()
            for v in self.adj[u]:
                if self.level[v] < 0 and self.cap[(u, v)] > 0:
                    self.level[v] = self.level[u] + 1
                    q.append(v)
        return self.level[t] >= 0

    def dfs(self, u, t, f):
        if u == t:
            return f
        for v in self.adj[u]:
            if self.level[v] == self.level[u] + 1 and self.cap[(u, v)] > 0:
                ret = self.dfs(v, t, min(f, self.cap[(u, v)]))
                if ret:
                    self.cap[(u, v)] -= ret
                    self.cap[(v, u)] += ret
                    return ret
        return 0

    def max_flow(self, s, t):
        flow = 0
        while self.bfs(s, t):
            while True:
                pushed = self.dfs(s, t, float('inf'))
                if not pushed:
                    break
                flow += pushed
        return flow

