    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0]); m = int(data[1])
    dinic = Dinic(n)
    idx = 2
    for _ in range(m):
        u = int(data[idx])-1; v = int(data[idx+1])-1; c = int(data[idx+2])
        idx += 3
        dinic.add_edge(u, v, c)
    print(dinic.max_flow(0, n-1))

