from collections import deque

def dinic(n, graph, s, t):
    def bfs():
        level = [-1]*n
        q = deque([s])
        level[s] = 0
        while q:
            u = q.popleft()
            for v, cap in graph[u]:
                if cap > 0 and level[v] < 0:
                    level[v] = level[u] + 1
                    q.append(v)
        return level

    def dfs(u, t, f, level, it):
        if u == t:
            return f
        for i in range(it[u], len(graph[u])):
            it[u] = i
            v, cap = graph[u][i]
            if cap > 0 and level[u] + 1 == level[v]:
                ret = dfs(v, t, min(f, cap), level, it)
                if ret > 0:
                    graph[u][i] = (v, cap - ret)
                    for j in range(len(graph[v])):
                        if graph[v][j][0] == u:
                            graph[v][j] = (u, graph[v][j][1] + ret)
                            break
                    return ret
        return 0

    flow = 0
    INF = 10**18
    while True:
        level = bfs()
        if level[t] < 0:
            return flow
        it = [0]*n
        while True:
            f = dfs(s, t, INF, level, it)
            if f == 0:
                break
            flow += f

