import sys
from collections import deque

class Dinic:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]

    def add_edge(self, fr, to, cap):
        forward = [to, cap, None]
        backward = [fr, 0, forward]
        forward[2] = backward
        self.graph[fr].append(forward)
        self.graph[to].append(backward)

    def bfs(self, s, t):
        self.level = [-1] * self.n
        q = deque([s])
        self.level[s] = 0
        while q:
            v = q.popleft()
            for to, cap, rev in self.graph[v]:
                if cap > 0 and self.level[to] < 0:
                    self.level[to] = self.level[v] + 1
                    q.append(to)
        return self.level[t] != -1

    def dfs(self, v, t, f):
        if v == t:
            return f
        for i in range(self.it[v], len(self.graph[v])):
            self.it[v] = i
            to, cap, rev = self.graph[v][i]
            if cap > 0 and self.level[v] < self.level[to]:
                d = self.dfs(to, t, min(f, cap))
                if d > 0:
                    self.graph[v][i][1] -= d
                    rev[1] += d
                    return d
        return 0

    def max_flow(self, s, t):
        flow = 0
        INF = 10**18
        while self.bfs(s, t):
            self.it = [0] * self.n
            while True:
                f = self.dfs(s, t, INF)
                if f == 0:
                    break
                flow += f
        return flow

def main():
    n, m, k = map(int, sys.stdin.readline().split())
    edges = []
    for _ in range(m):
        u, v, c = map(int, sys.stdin.readline().split())
        edges.append((u-1, v-1, c))

    # 二分答案时间 T，判断能否在 T 时间内运送 k 辆车
    def can(T):
        # 构建分层图：每个时间层一个节点，层间边容量为原图容量
        nodes = n * (T + 1)
        dinic = Dinic(nodes)
        s = 0
        t = n - 1 + T * n  # 第 T 层的城市 n-1

        # 添加层内边：从时间 t 的 u 到时间 t+1 的 v，容量为 c
        for u, v, c in edges:
            for t in range(T):
                dinic.add_edge(u + t*n, v + (t+1)*n, c)

        # 添加等待边：从时间 t 的 u 到时间 t+1 的 u，容量无穷大
        INF = 10**18
        for t in range(T):
            for i in range(n):
                dinic.add_edge(i + t*n, i + (t+1)*n, INF)

        flow = dinic.max_flow(s, t)
        return flow >= k

    # 先检查是否有路径
    dinic_test = Dinic(n)
    for u, v, c in edges:
        dinic_test.add_edge(u, v, c)
    if dinic_test.max_flow(0, n-1) == 0:
        print(-1)
        return

    lo, hi = 1, 100000
    while lo < hi:
        mid = (lo + hi) // 2
        if can(mid):
            hi = mid
        else:
            lo = mid + 1
    print(lo)

if __name__ == '__main__':
    main()

import sys
from collections import deque

class Dinic:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]
        self.edges = []

    def add_edge(self, fr, to, cap):
        forward = [to, cap, len(self.graph[to]), fr, to]  # to, cap, rev, original u, v
        backward = [fr, 0, len(self.graph[fr]), fr, to]
        self.graph[fr].append(forward)
        self.graph[to].append(backward)
        self.edges.append((fr, to))

    def bfs(self, s, t):
        self.level = [-1] * self.n
        q = deque([s])
        self.level[s] = 0
        while q:
            v = q.popleft()
            for to, cap, rev, u, vv in self.graph[v]:
                if cap > 0 and self.level[to] < 0:
                    self.level[to] = self.level[v] + 1
                    q.append(to)
        return self.level[t] != -1

    def dfs(self, v, t, f):
        if v == t:
            return f
        for i in range(self.it[v], len(self.graph[v])):
            self.it[v] = i
            to, cap, rev, u, vv = self.graph[v][i]
            if cap > 0 and self.level[v] < self.level[to]:
                d = self.dfs(to, t, min(f, cap))
                if d > 0:
                    self.graph[v][i][1] -= d
                    self.graph[to][rev][1] += d
                    return d
        return 0

    def max_flow(self, s, t):
        flow = 0
        INF = 10**18
        while self.bfs(s, t):
            self.it = [0] * self.n
            while True:
                f = self.dfs(s, t, INF)
                if f == 0:
                    break
                flow += f
        return flow

    def min_cut(self, s, t):
        flow = self.max_flow(s, t)
        # BFS 找可达集
        visited = [False] * self.n
        q = deque([s])
        visited[s] = True
        while q:
            v = q.popleft()
            for to, cap, rev, u, vv in self.graph[v]:
                if cap > 0 and not visited[to]:
                    visited[to] = True
                    q.append(to)
        cut_edges = []
        for i, (u, v) in enumerate(self.edges):
            if visited[u] and not visited[v]:
                cut_edges.append((u+1, v+1))  # 1-indexed
        return flow, cut_edges

def main():
    n, m, s, t = map(int, sys.stdin.readline().split())
    dinic = Dinic(n)
    for _ in range(m):
        u, v, c = map(int, sys.stdin.readline().split())
        dinic.add_edge(u-1, v-1, c)
    flow, cut = dinic.min_cut(s-1, t-1)
    print(flow)
    print(len(cut))
    for u, v in cut:
        print(u, v)

