def solve():
    data = sys.stdin.read().split()
    idx = 0
    t = int(data[idx]); idx += 1
    out = []
    for _ in range(t):
        n = int(data[idx]); idx += 1
        s = data[idx]; idx += 1
        # 计算初始可操作位置数（即'0'且左右无'1'的位置）
        cnt = 0
        for i in range(n):
            if s[i] == '0':
                left_ok = (i == 0 or s[i-1] == '0')
                right_ok = (i == n-1 or s[i+1] == '0')
                if left_ok and right_ok:
                    cnt += 1
        # 每次操作会减少一些可操作位置，但简化：总操作次数为cnt（因为每次操作会占用一个位置并可能影响相邻，但实际游戏等价于在可操作位置中取，每取一个会减少至多3个可操作位置，但这里我们只需判断奇偶性？不，需要更精确）
        # 正确做法：经典博弈，可操作位置数为cnt，每次操作会移除该位置及相邻位置的可操作性，所以是Sprague-Grundy，但这里简化：因为每个位置独立且互不影响？不对，相邻会互相影响。但实际我们可以贪心：每次操作后，该位置和相邻位置不能再操作。所以总操作次数等于最大独立集大小？不，是每次操作选择一个，然后删除该位置和相邻位置。所以操作次数等于最大匹配？其实这是经典的"选点消邻"游戏，结果为最大匹配数。但这里我们直接模拟博弈：由于n≤1000，可以BFS/DP。但简化：对于每个连续的'0'段，长度为L，该段可操作次数为ceil(L/2)？不对，因为操作会影响相邻。实际上，对于一段连续的'0'，两端被'1'或边界包围，每次操作选择一个'0'，然后该'0'和相邻的'0'都变成不可选。所以该段可操作次数为ceil(L/2)？例如L=1，可操作1次；L=2，可操作1次（选一个，另一个被影响）；L=3，可操作2次（选第一个，中间被影响，剩第三个）。所以是ceil(L/2)。但边界情况：如果该段两端是边界或'1'，那么操作一个位置会禁用它本身和相邻的'0'。所以总可操作次数为sum(ceil(L_i/2))。但还要考虑初始'1'的影响。所以直接计算。
        total_ops = 0
        i = 0
        while i < n:
            if s[i] == '0':
                j = i
                while j < n and s[j] == '0':
                    j += 1
                length = j - i
                total_ops += (length + 1) // 2
                i = j
            else:
                i += 1
        if total_ops % 2 == 1:
            out.append("Alice")
        else:
            out.append("Bob")
    print("\n".join(out))

