def construct(n):
    if n == 1:
        return [1]
    if n == 2:
        return [1, 2]
    if n == 3:
        return [1, 3, 2]
    # 构造方法：首尾交替，例如1, n, 2, n-1, 3, n-2, ...
    # 这样相邻差为 n-1, n-2, n-3, ... 但需要确保所有差不同。
    # 实际上，经典构造：1, n, 2, n-1, 3, n-2, ... 得到的差为 n-1, n-2, n-3, ... 直到1。
    # 但注意当n为奇数时，中间会有一个元素重复？需要处理。
    res = []
    left = 1
    right = n
    while left <= right:
        if left == right:
            res.append(left)
        else:
            res.append(left)
            res.append(right)
        left += 1
        right -= 1
    # 检查是否满足条件？但这样构造的差是否互不相同？例如n=4: [1,4,2,3] 差为3,2,1 不同。n=5: [1,5,2,4,3] 差为4,3,2,1 不同。n=6: [1,6,2,5,3,4] 差为5,4,3,1? 不对，3和4差1，但之前有？检查：5,4,3,2,1？实际上 [1,6,2,5,3,4] 差为5,4,3,2,1 都不同。所以可行。
    return res

