import math

def is_prime(x):
    if x < 2:
        return False
    for i in range(2, int(math.isqrt(x))+1):
        if x % i == 0:
            return False
    return True

def solve():
    data = sys.stdin.read().split()
    t = int(data[0])
    out = []
    for i in range(1, t+1):
        n = int(data[i])
        if n == 1:
            out.append("Bob")
        elif is_prime(n):
            out.append("Alice")
        else:
            # 尝试找因子，如果存在因子d使得n/d是质数，则Alice胜，否则Bob胜
            win = False
            for d in range(2, int(math.isqrt(n))+1):
                if n % d == 0:
                    if is_prime(n//d) or is_prime(d):
                        # 但除以d得n/d，除以n//d得d，如果其中一个是质数则胜
                        win = True
                        break
            if win:
                out.append("Alice")
            else:
                out.append("Bob")
    print("\n".join(out))

