    b = [1]*n
    # 贪心：每个选1，如果和前一个相同，则选2（如果2是因子），否则选a[i]本身
    for i in range(n):
        if i == 0:
            b[i] = 1 if a[i] % 1 == 0 else -1
        else:
            if b[i-1] != 1 and a[i] % 1 == 0:
                b[i] = 1
            elif b[i-1] != 2 and a[i] % 2 == 0:
                b[i] = 2
            elif b[i-1] != a[i] and a[i] % a[i] == 0:
                b[i] = a[i]
            else:
                # 尝试找其他因子
                found = False
                for d in range(1, int(a[i]**0.5)+1):
                    if a[i] % d == 0:
                        if d != b[i-1]:
                            b[i] = d; found = True; break
                        if a[i]//d != b[i-1]:
                            b[i] = a[i]//d; found = True; break
                if not found:
                    print(-1); return
    print(' '.join(map(str, b)))
