class SegmentTree:
    def __init__(self, n):
        self.n = n
        self.sum = [0]*(4*n)
        self.lazy = [0]*(4*n)
    def push_down(self, node, l, r):
        if self.lazy[node]:
            mid = (l+r)//2
            left_len = mid - l + 1
            right_len = r - mid
            self.sum[node*2] += self.lazy[node]*left_len
            self.sum[node*2+1] += self.lazy[node]*right_len
            self.lazy[node*2] += self.lazy[node]
            self.lazy[node*2+1] += self.lazy[node]
            self.lazy[node] = 0
    def update(self, node, l, r, ql, qr):
        if ql <= l and r <= qr:
            self.sum[node] += (r-l+1)
            self.lazy[node] += 1
            return
        self.push_down(node, l, r)
        mid = (l+r)//2
        if ql <= mid:
            self.update(node*2, l, mid, ql, qr)
        if qr > mid:
            self.update(node*2+1, mid+1, r, ql, qr)
        self.sum[node] = self.sum[node*2] + self.sum[node*2+1]
    def query(self, node, l, r, ql, qr):
        if ql <= l and r <= qr:
            return self.sum[node]
        self.push_down(node, l, r)
        mid = (l+r)//2
        res = 0
        if ql <= mid:
            res += self.query(node*2, l, mid, ql, qr)
        if qr > mid:
            res += self.query(node*2+1, mid+1, r, ql, qr)
        return res

