            self.apply_add(idx*2, l, mid, self.add[idx])
            self.apply_add(idx*2+1, mid+1, r, self.add[idx])
            self.mul[idx] = 1
            self.add[idx] = 0
    def update(self, idx, l, r, ql, qr, op, v):
        if ql <= l and r <= qr:
            if op == 1:
                self.apply_add(idx, l, r, v)
            else:
                self.apply_mul(idx, v)
            return
        self.push_down(idx, l, r)
        mid = (l+r)//2
        if ql <= mid: self.update(idx*2, l, mid, ql, qr, op, v)
