# 由于初始为0，平方根操作无效，但为了通用，使用线段树维护最大值和和
# 但题目没有初始化操作，所以直接输出0即可。但为了完整性，给出线段树实现。
class SegTree:
    def __init__(self, n):
        self.n = n
        self.sum = [0]*(4*n)
        self.max = [0]*(4*n)
    def update(self, idx, l, r, ql, qr):
        if self.max[idx] <= 1:
            return
        if l == r:
            self.sum[idx] = int(math.sqrt(self.sum[idx]))
            self.max[idx] = self.sum[idx]
            return
        mid = (l+r)//2
        if ql <= mid: self.update(idx*2, l, mid, ql, qr)
        if qr > mid: self.update(idx*2+1, mid+1, r, ql, qr)
        self.sum[idx] = self.sum[idx*2] + self.sum[idx*2+1]
        self.max[idx] = max(self.max[idx*2], self.max[idx*2+1])
    def query(self, idx, l, r, ql, qr):
        if ql <= l and r <= qr:
            return self.sum[idx]
        mid = (l+r)//2
        res = 0
        if ql <= mid: res += self.query(idx*2, l, mid, ql, qr)
        if qr > mid: res += self.query(idx*2+1, mid+1, r, ql, qr)
        return res
