class SegmentTree:
    def __init__(self, n):
        self.n = n
        self.maxv = [0]*(4*n)
        self.minv = [0]*(4*n)
        self.add = [0]*(4*n)
        self.rev = [False]*(4*n)
    def apply_add(self, idx, v):
        self.maxv[idx] += v
        self.minv[idx] += v
        self.add[idx] += v
    def apply_rev(self, idx):
        self.maxv[idx], self.minv[idx] = -self.minv[idx], -self.maxv[idx]
        self.add[idx] = -self.add[idx]
        self.rev[idx] ^= True
    def push_down(self, idx):
        if self.rev[idx]:
            self.apply_rev(idx*2)
            self.apply_rev(idx*2+1)
            self.rev[idx] = False
        if self.add[idx] != 0:
            self.apply_add(idx*2, self.add[idx])
            self.apply_add(idx*2+1, self.add[idx])
            self.add[idx] = 0
    def update(self, idx, l, r, ql, qr, op, v):
        if ql <= l and r <= qr:
            if op == 1:
                self.apply_add(idx, v)
            else:
                self.apply_rev(idx)
            return
        self.push_down(idx)
        mid = (l+r)//2
        if ql <= mid: self.update(idx*2, l, mid, ql, qr, op, v)
        if qr > mid: self.update(idx*2+1, mid+1, r, ql, qr, op, v)
        self.maxv[idx] = max(self.maxv[idx*2], self.maxv[idx*2+1])
        self.minv[idx] = min(self.minv[idx*2], self.minv[idx*2+1])
    def query(self, idx, l, r, ql, qr):
        if ql <= l and r <= qr:
            return self.maxv[idx] - self.minv[idx]
        self.push_down(idx)
        mid = (l+r)//2
        # 需要分别查询最大和最小，所以直接递归返回差值
        # 更简单：查询最大值和最小值
        def query_max(idx, l, r, ql, qr):
            if ql <= l and r <= qr: return self.maxv[idx]
            self.push_down(idx)
            mid = (l+r)//2
            res = -10**18
            if ql <= mid: res = max(res, query_max(idx*2, l, mid, ql, qr))
            if qr > mid: res = max(res, query_max(idx*2+1, mid+1, r, ql, qr))
            return res
        def query_min(idx, l, r, ql, qr):
            if ql <= l and r <= qr: return self.minv[idx]
            self.push_down(idx)
            mid = (l+r)//2
            res = 10**18
            if ql <= mid: res = min(res, query_min(idx*2, l, mid, ql, qr))
            if qr > mid: res = min(res, query_min(idx*2+1, mid+1, r, ql, qr))
            return res
        return query_max(1,1,self.n,ql,qr) - query_min(1,1,self.n,ql,qr)
