class SegmentTree:
    def __init__(self, data):
        self.n = len(data)
        self.size = 1
        while self.size < self.n:
            self.size <<= 1
        self.tree = [0] * (2 * self.size)
        self.lazy = [0] * (2 * self.size)
        for i in range(self.n):
            self.tree[self.size + i] = data[i]
        for i in range(self.size - 1, 0, -1):
            self.tree[i] = self.tree[i*2] + self.tree[i*2+1]

    def _apply(self, idx, val, seg_len):
        self.tree[idx] += val * seg_len
        if idx < self.size:
            self.lazy[idx] += val

    def _push(self, idx, seg_len):
        if self.lazy[idx] != 0:
            self._apply(idx*2, self.lazy[idx], seg_len//2)
            self._apply(idx*2+1, self.lazy[idx], seg_len - seg_len//2)
            self.lazy[idx] = 0

    def _update(self, l, r, val, idx, left, right):
        if l <= left and right <= r:
            self._apply(idx, val, right - left + 1)
            return
        self._push(idx, right - left + 1)
        mid = (left + right) // 2
        if l <= mid:
            self._update(l, r, val, idx*2, left, mid)
        if r > mid:
            self._update(l, r, val, idx*2+1, mid+1, right)
        self.tree[idx] = self.tree[idx*2] + self.tree[idx*2+1]

    def update(self, l, r, val):
        self._update(l, r, val, 1, 1, self.size)

    def _query(self, l, r, idx, left, right):
        if l <= left and right <= r:
            return self.tree[idx]
        self._push(idx, right - left + 1)
        mid = (left + right) // 2
        res = 0
        if l <= mid:
            res += self._query(l, r, idx*2, left, mid)
        if r > mid:
            res += self._query(l, r, idx*2+1, mid+1, right)
        return res

    def query(self, l, r):
        return self._query(l, r, 1, 1, self.size)

