def kmp_search(s, p):
    n, m = len(s), len(p)
    if m > n:
        return -1
    # build prefix function
    pi = [0] * m
    j = 0
    for i in range(1, m):
        while j > 0 and p[i] != p[j]:
            j = pi[j-1]
        if p[i] == p[j]:
            j += 1
            pi[i] = j
    # search
    j = 0
    for i in range(n):
        while j > 0 and s[i] != p[j]:
            j = pi[j-1]
        if s[i] == p[j]:
            j += 1
        if j == m:
            return i - m + 2  # 1-indexed
    return -1

