input = sys.stdin.readline
k = int(input().strip())
T = input().strip()
patterns = [input().strip() for _ in range(k)]

# 构建所有模式串的 AC 自动机（使用 KMP 的扩展思想）
# 由于总长度有限，用字典树+失败链接
class Node:
    def __init__(self):
        self.next = {}
        self.fail = None
        self.output = []  # 存储模式串索引

root = Node()
# 插入模式串
for idx, p in enumerate(patterns):
    cur = root
    for ch in p:
        if ch not in cur.next:
            cur.next[ch] = Node()
        cur = cur.next[ch]
    cur.output.append(idx)

# BFS 构建失败链接
from collections import deque
q = deque()
for ch, node in root.next.items():
    node.fail = root
    q.append(node)
while q:
    cur = q.popleft()
    for ch, nxt in cur.next.items():
        fail = cur.fail
        while fail and ch not in fail.next:
            fail = fail.fail
        if fail:
            nxt.fail = fail.next[ch]
        else:
            nxt.fail = root
        nxt.output.extend(nxt.fail.output)  # 传递输出
        q.append(nxt)

# 匹配 T
counts = [0] * k
cur = root
for ch in T:
    while cur != root and ch not in cur.next:
        cur = cur.fail
    if ch in cur.next:
        cur = cur.next[ch]
    else:
        cur = root
    for idx in cur.output:
        counts[idx] += 1

print('\n'.join(map(str, counts)))

def kmp_search(s, p):
    n, m = len(s), len(p)
    if m == 0: return 1
    # 构建前缀函数
    pi = [0] * m
    for i in range(1, m):
        j = pi[i-1]
        while j > 0 and p[i] != p[j]:
            j = pi[j-1]
        if p[i] == p[j]:
            j += 1
        pi[i] = j
    # 匹配
    j = 0
    for i in range(n):
        while j > 0 and s[i] != p[j]:
            j = pi[j-1]
        if s[i] == p[j]:
            j += 1
        if j == m:
            return i - m + 2  # 1-based
    return -1

