from collections import deque

def max_flow(n, s, t, edges):
    graph = [[] for _ in range(n+1)]
    for u, v, c in edges:
        graph[u].append([v, c, len(graph[v])])
        graph[v].append([u, 0, len(graph[u])-1])
    flow = 0
    while True:
        parent = [-1]*(n+1)
        parent[s] = 0
        q = deque([s])
        while q and parent[t] == -1:
            u = q.popleft()
            for v, cap, rev in graph[u]:
                if cap > 0 and parent[v] == -1:
                    parent[v] = u
                    q.append(v)
        if parent[t] == -1:
            break
        min_cap = float('inf')
        v = t
        while v != s:
            u = parent[v]
            for i, (to, cap, rev) in enumerate(graph[u]):
                if to == v and cap > 0:
                    min_cap = min(min_cap, cap)
                    break
            v = u
        v = t
        while v != s:
            u = parent[v]
            for i, (to, cap, rev) in enumerate(graph[u]):
                if to == v and cap > 0:
                    graph[u][i][1] -= min_cap
                    graph[v][rev][1] += min_cap
                    break
            v = u
        flow += min_cap
    return flow

