def solve():
    data = sys.stdin.read().strip().split()
    T = int(data[0])
    res = []
    for i in range(1, T+1):
        n = int(data[i])
        if n == 1:
            res.append("1")
        elif n == 2 or n == 3:
            res.append("-1")
        else:
            # 构造：先偶数升序，再奇数升序
            perm = []
            for x in range(2, n+1, 2):
                perm.append(x)
            for x in range(1, n+1, 2):
                perm.append(x)
            # 检查相邻差是否>=2，如果不满足，尝试调整（对于n>=4此构造通常有效，但需微调）
            # 检查n=4时构造为2 4 1 3，差分别为2,3,2，OK。n=5：2 4 1 3 5，差2,3,2,2 OK。
            # 但n=6: 2 4 6 1 3 5，差2,2,5,2,2 OK。n=7: 2 4 6 1 3 5 7，差2,2,5,2,2,2 OK。
            # 实际上此构造对n>=4恒成立，但需要证明，此处直接输出。
            res.append(" ".join(map(str, perm)))
    print("\n".join(res))

if __name__ == "__main__":
    solve()

