import sys

def solve():
    data = sys.stdin.read().strip().split()
    T = int(data[0])
    res = []
    for i in range(1, T+1):
        a = int(data[2*i-1])
        b = int(data[2*i])
        # 分析：当|a-b| > 1时，先手可以控制，必胜；当|a-b| <= 1时，后手有策略。
        if abs(a - b) > 1:
            res.append("Alice")
        else:
            # 当|a-b|<=1时，进一步判断：如果a+b是偶数则Bob胜，否则Alice胜？
            # 实际结论：当|a-b|<=1时，Bob胜当且仅当a+b为偶数，否则Alice胜。
            if (a + b) % 2 == 0:
                res.append("Bob")
            else:
                res.append("Alice")
    print("\n".join(res))

if __name__ == "__main__":
    solve()

